python3 -c "
import json

# Load all classify files to extract master assignments
files = {
    '01_04': '/tmp/classify_01_04.json',
    '05_09': '/tmp/classify_05_09.json',
    '10_14': '/tmp/classify_10_14_final.json',
    '15_19': '/tmp/classify_15_19.json',
    '20_24': '/tmp/classify_20_24.json',
}

for label, path in files.items():
    try:
        with open(path) as f:
            data = json.load(f)
    except Exception as e:
        print(f'{label}: ERROR {e}')
        continue

    # Detect structure
    if isinstance(data, list):
        print(f'{label}: list of {len(data)} items')
    elif isinstance(data, dict):
        keys = list(data.keys())
        print(f'{label}: dict keys={keys}')
        # Check for new_masters or similar
        for k in keys:
            v = data[k]
            if isinstance(v, list):
                print(f'  {k}: list[{len(v)}]')
                if len(v) > 0 and isinstance(v[0], dict):
                    print(f'    first item keys={list(v[0].keys())[:15]}')
            elif isinstance(v, dict):
                print(f'  {k}: dict keys={list(v.keys())[:10]}')
    print()
"

python3 -c "
import json

# Extract new master proposals from each classify file

def show_new_masters(label, data):
    print(f'=== {label} ===')
    if isinstance(data, dict):
        for dk, dv in data.items():
            if dk in ('meta','_summary','summary','classification_date','classification_note','generated','description'):
                continue
            if isinstance(dv, dict) and 'new_masters_proposed' in dv:
                nm = dv['new_masters_proposed']
                if isinstance(nm, list):
                    print(f'  {dv.get(\"domain_name\", dk)}:')
                    for m in nm:
                        if isinstance(m, dict):
                            name = m.get('name') or m.get('master_name') or m.get('title','unnamed')
                            concepts = m.get('concepts') or m.get('assigned_concepts') or m.get('concept_count') or m.get('count') or '?'
                            note = m.get('note') or ''
                            print(f'    - {name} ({concepts} concepts) {note}')
                        elif isinstance(m, str):
                            print(f'    - {m}')
            elif isinstance(dv, dict) and 'proposed_new_masters' in dv:
                nm = dv['proposed_new_masters']
                if isinstance(nm, list):
                    print(f'  {dv.get(\"domain_name\", dk)}:')
                    for m in nm:
                        if isinstance(m, dict):
                            name = m.get('name') or m.get('master_name') or 'unnamed'
                            concepts = m.get('assigned_concept_count') or m.get('concept_count') or m.get('count') or len(m.get('assigned_concepts',[]))
                            print(f'    - {name} ({concepts} concepts)')
            elif isinstance(dv, list):
                print(f'  {dk}: list[{len(dv)}]')
                for item in dv:
                    if isinstance(item, dict):
                        name = item.get('name') or item.get('master_name') or item.get('title','unnamed')
                        concepts = item.get('concept_count') or item.get('assigned_concept_count') or len(item.get('assigned_concepts',[]))
                        note = item.get('note','')[:80]
                        print(f'    - {name} ({concepts} concepts) | {note}')

    print()

with open('/tmp/classify_01_04.json') as f:
    show_new_masters('01_04', json.load(f))
with open('/tmp/classify_05_09.json') as f:
    show_new_masters('05_09', json.load(f))
with open('/tmp/classify_10_14_final.json') as f:
    show_new_masters('10_14', json.load(f))
with open('/tmp/classify_15_19.json') as f:
    show_new_masters('15_19', json.load(f))
with open('/tmp/classify_20_24.json') as f:
    show_new_masters('20_24', json.load(f))
" 2>&1 | head -200

