    return None

arguments.newString:
def parse_concept_line(line):
    """Extract concept name from various formats.
    Accepts [[Concept_Name]], [[Name]], or plain Concept_Name."""
    line = line.strip().rstrip('|')
    # Prefer explicit Concept_ prefix
    m = re.search(r'\[\[(Concept_\w+)\]\]', line)
    if m:
        return m.group(1)
    m = re.search(r'`(Concept_\w+)`', line)
    if m:
        return m.group(1)
    # Accept any [[WikiLink]] that looks like a concept
    m = re.search(r'\[\[(\w+(?:_\w+)+)\]\]', line)
    if m and not m.group(1).startswith(('http', 'Entity_', 'Source_', 'Master_', 'Companion_')):
        # Normalize: if no Concept_ prefix, add it
        name = m.group(1)
        if not name.startswith('Concept_'):
            name = 'Concept_' + name
        return name
    # Plain text fallback (for markdown tables)
    m = re.search(r'Concept_\w+', line)
    if m:
        return m.group(0)
    return None

